        ActivityCategories.register(CategoryMatcher::add);
    }

    private static Category find(String q, boolean strict)
    {
        Category exact = BY_ALIAS.get(q);
        if (exact != null) { return exact; }
        if (strict || q.length() < 3) { return null; }
        Category candidate = null;
        for (Map.Entry<String, Category> entry : BY_ALIAS.entrySet())
        {
            if (entry.getKey().startsWith(q))
            {
                if (candidate != null && candidate != entry.getValue()) { return null; }
                candidate = entry.getValue();
            }
        }
        return candidate;
    }

    public static Query parse(String input, boolean strict)
    {
        String normalized = normalize(input);
        boolean exclusive = normalized.startsWith("@");
        String q = exclusive ? normalize(normalized.substring(1)) : normalized;
        if (q.isEmpty()) { return new Query(input, false, Collections.emptyList()); }
        // The @ form of bare combat skill names keeps the original broad skill search.
        if (exclusive && (q.equals("strength") || q.equals("attack") || q.equals("defence") || q.equals("defense")))
        {
            String skill = q.equals("defense") ? "defence" : q;
            return new Query(input, true, Collections.singletonList(BY_ALIAS.get(skill + " skill")));
        }
        // Bare keywords focus on supplies while @ retains the familiar broad categories.
        if (exclusive && (q.equals("magic") || q.equals("mage")))
        {
            return new Query(input, true, Collections.singletonList(BY_ALIAS.get("magic gear")));
        }
        if (exclusive && (q.equals("ranged") || q.equals("range") || q.equals("ranging")))
        {
            return new Query(input, true, Collections.singletonList(BY_ALIAS.get("ranged gear")));
        }
        if (exclusive && q.equals("prayer"))
        {
            return new Query(input, true, Collections.singletonList(BY_ALIAS.get("all prayer")));
        }
        Category direct = find(q, strict);
        if (direct != null) { return new Query(input, exclusive, Collections.singletonList(direct)); }
        // Two-category intersections: `ranged boots`, `prayer legs`, `magic helmets`.
        for (int i = 0; i < q.length(); i++)
        {
            if (q.charAt(i) != ' ') { continue; }
            // Composite terms require COMPLETE aliases: avoids transient search flicker.
            String first = q.substring(0, i);
            Category left = BY_ALIAS.get(first);
            Category right = BY_ALIAS.get(q.substring(i + 1));
            // Compound skill + slot searches should match gear, not consumables.
            if (right != null)
            {
                if (first.equals("ranged") || first.equals("range")) { left = BY_ALIAS.get("ranged gear"); }
                else if (first.equals("magic")) { left = BY_ALIAS.get("magic gear"); }
                else if (first.equals("prayer")) { left = BY_ALIAS.get("prayer gear"); }
            }
            if (left != null && right != null && left != right)
            {
                return new Query(input, exclusive, Arrays.asList(left, right));
            }
        }
        return new Query(input, false, Collections.emptyList());
    }

    public static boolean isCategoryQuery(String search, boolean strict)
    {
        return parse(search, strict).isCategory();
    }
    public static boolean matches(String search, String itemName, boolean strict)
    {
        return parse(search, strict).matches(ItemFacts.nameOnly(itemName));
    }
    public static boolean matches(String search, ItemFacts item, boolean strict)
    {
        return parse(search, strict).matches(item);
    }
    public static Map<String, List<String>> catalog()
    {
        Map<String, List<String>> result = new LinkedHashMap<>();
        for (Category c : CATEGORIES) { result.put(c.title, c.aliases); }
        return Collections.unmodifiableMap(result);
    }
}

package com.smartbanksearch;

/**
 * Normalized item metadata. Slot and combat stats are supplied by RuneLite when available.
 * Unknown metadata uses slot=-1 and equipable=false; name-only rules remain available.
 * Pure Java class so matching rules can be tested without a running game client.
 */
public final class ItemFacts
{
    public final String name;
    public final int slot;
    public final boolean equipable;
    public final boolean twoHanded;
    public final int meleeAttack;
    public final int rangedAttack;
    public final int magicAttack;
    public final int meleeStrength;
    public final int rangedStrength;
    public final float magicDamage;
    public final int prayerBonus;
    public final int defence;

    public ItemFacts(String name, int slot, boolean equipable, boolean twoHanded,
                     int meleeAttack, int rangedAttack, int magicAttack, int meleeStrength,
                     int rangedStrength, float magicDamage, int prayerBonus, int defence)
    {
        this.name = name == null ? "" : name;
        this.slot = slot;
        this.equipable = equipable;
        this.twoHanded = twoHanded;
        this.meleeAttack = meleeAttack;
        this.rangedAttack = rangedAttack;
        this.magicAttack = magicAttack;
        this.meleeStrength = meleeStrength;
        this.rangedStrength = rangedStrength;
        this.magicDamage = magicDamage;
        this.prayerBonus = prayerBonus;
        this.defence = defence;
    }

    public static ItemFacts nameOnly(String name)
    {
        return new ItemFacts(name, -1, false, false, 0, 0, 0, 0, 0, 0f, 0, 0);
    }

    public boolean worn() { return equipable || slot >= 0; }
}

package com.smartbanksearch;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("smartbanksearch")
public interface SmartBankSearchConfig extends Config
{
    @ConfigItem(keyName = "enabled", name = "Enable smart search",
        description = "Add semantic category matches to the native bank search", position = 0)
    default boolean enabled() { return true; }

    @ConfigItem(keyName = "strict", name = "Full category phrases only",
        description = "Avoid ambiguous partial matches. Recommended ON. e.g. 'herb' and 'ranged gear'", position = 1)
    default boolean strict() { return true; }

    @ConfigItem(keyName = "diagnostics", name = "Diagnostic logging",
        description = "Log the first 25 checked items per category search. Only enable when troubleshooting.", position = 2)
    default boolean diagnostics() { return false; }
}

package com.smartbanksearch;

import com.google.inject.Provides;
import java.util.LinkedHashMap;
import java.util.Map;
import javax.swing.SwingUtilities;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.events.ScriptCallbackEvent;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemEquipmentStats;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/** Non-invasive integration with RuneLite's built-in bank search filter. */
@PluginDescriptor(
    name = "Smart Bank Search",
    description = "Automatic semantic bank categories, equipment slots, combined and category-only searches",
    tags = {"bank", "search", "category", "herb", "gear", "equipment"}
)
public class SmartBankSearchPlugin extends Plugin
{
    private static final Logger LOG = LoggerFactory.getLogger(SmartBankSearchPlugin.class);
    private static final int MAX_CACHE = 4000;

    @Inject private Client client;
    @Inject private ItemManager itemManager;
    @Inject private SmartBankSearchConfig config;
    @Inject private ConfigManager configManager;
    @Inject private ClientToolbar clientToolbar;

    private volatile NavigationButton categoryDirectoryButton;
    private volatile boolean directoryEnabled;

    private String lastQuery = null;
    private boolean lastStrict;
    private CategoryMatcher.Query parsedQuery;
    private int diagnosticsForQuery = 0;

    // Item definitions and stats are stable for a client's lifetime. Avoid recomputing
    // composition / stats for thousands of bank items on every search keystroke.
    private final Map<Integer, ItemFacts> itemCache = new LinkedHashMap<Integer, ItemFacts>(256, 0.75f, true)
    {
        @Override protected boolean removeEldestEntry(Map.Entry<Integer, ItemFacts> entry)
        {
            return size() > MAX_CACHE;
        }
    };

    @Provides
    SmartBankSearchConfig provideConfig(ConfigManager manager)
    {
        return manager.getConfig(SmartBankSearchConfig.class);
    }

    @Override protected void startUp()
    {
        directoryEnabled = true;
        // One compact sidebar tab; categories are read directly from the
        // existing offline matcher rather than stored in a second catalogue.
        SwingUtilities.invokeLater(() ->
        {
            if (!directoryEnabled) { return; }
            categoryDirectoryButton = NavigationButton.builder()
                .tooltip("Smart Bank Search categories")
                .icon(ImageUtil.loadImageResource(SmartBankSearchPlugin.class,
                    "/smartbanksearch/icon.png"))
                .panel(new CategoryDirectoryPanel(configManager))
                .priority(80)
                .build();
            clientToolbar.addNavigation(categoryDirectoryButton);
        });
        LOG.info("[SmartBankSearch] v1.5 started; {} categories", CategoryMatcher.catalog().size());
    }

    @Override protected void shutDown()
    {
        // The callback may still be queued when a plugin is disabled quickly.
        // Keep it from creating an orphaned sidebar button after shutdown.
        directoryEnabled = false;
        NavigationButton directory = categoryDirectoryButton;
        categoryDirectoryButton = null;
        if (directory != null)
        {
            SwingUtilities.invokeLater(() -> clientToolbar.removeNavigation(directory));
        }
        itemCache.clear();
        parsedQuery = null;
        lastQuery = null;
        LOG.info("[SmartBankSearch] stopped");
    }

    @Subscribe
    public void onScriptCallbackEvent(ScriptCallbackEvent event)
    {
        if (!"bankSearchFilter".equals(event.getEventName()) || !config.enabled())
        {
            return;
        }

        int intSize = client.getIntStackSize();
        int objSize = client.getObjectStackSize();
        if (intSize < 2 || objSize < 1)
        {
            return;
        }
        Object searchObject = client.getObjectStack()[objSize - 1];
        if (!(searchObject instanceof String))
        {
            return;
        }
        String search = (String) searchObject;
        if (!search.equals(lastQuery) || lastStrict != config.strict() || parsedQuery == null)
        {
            lastQuery = search;
            lastStrict = config.strict();
            parsedQuery = CategoryMatcher.parse(search, lastStrict);
            diagnosticsForQuery = 0;
            if (config.diagnostics())
            {
                // Never persist the player's typed bank query to diagnostic logs.
                LOG.info("[SmartBankSearch] category='{}' exclusive={}",
                    parsedQuery.getCategoryName(), parsedQuery.isExclusive());
            }
        }
        if (!parsedQuery.isCategory())
        {
            // Unknown searches, advanced GE/qty filters and Bank Tags are untouched.
            return;
        }

        int[] stack = client.getIntStack();
        int itemId = stack[intSize - 1];
        if (itemId < 0) { return; }
        int previous = stack[intSize - 2];
        ItemFacts item = itemCache.computeIfAbsent(itemId, this::readItem);
        boolean matched = parsedQuery.matches(item);

        // Most queries augment RuneLite's native result. Bare "prayer" is a
        // focused exception to prevent unrelated prayer-named items appearing.
        stack[intSize - 2] = parsedQuery.resolveBankMatch(previous, matched);

        if (config.diagnostics() && diagnosticsForQuery++ < 25)
        {
            // Item names are unnecessary for diagnostics and can reveal bank contents.
            LOG.info("[SmartBankSearch] slot={} categoryMatch={} native={} final={}",
                item.slot, matched, previous, stack[intSize - 2]);
        }
    }

    private ItemFacts readItem(int id)
    {
        ItemComposition composition = itemManager.getItemComposition(id);
        String name = composition == null ? "" : composition.getName();
        // RuneLite returns null stats for notes. Canonical ID resolves the base item.
        int canonicalId = itemManager.canonicalize(id);
        ItemStats stats = itemManager.getItemStats(canonicalId);
        if (stats == null || stats.getEquipment() == null)
        {
            return ItemFacts.nameOnly(name);
        }
        ItemEquipmentStats gear = stats.getEquipment();
        int attack = Math.max(gear.getAstab(), Math.max(gear.getAslash(), gear.getAcrush()));
        int defence = Math.max(gear.getDstab(), Math.max(gear.getDslash(),
            Math.max(gear.getDcrush(), Math.max(gear.getDrange(), gear.getDmagic()))));
        return new ItemFacts(name, gear.getSlot(), stats.isEquipable(), gear.isTwoHanded(),
            attack, gear.getArange(), gear.getAmagic(), gear.getStr(), gear.getRstr(),
            gear.getMdmg(), gear.getPrayer(), defence);
    }
}

package com.smartbanksearch;
import java.util.HashSet;
import java.util.Set;

/** Run with JUnit/Gradle or plain javac/java to verify the v1.5 activity catalog. */
public final class ActivityCategoriesSelfTest
{
    private static int checks;
    private static void check(boolean value, String message)
    {
        checks++;
        if (!value) { throw new AssertionError(message); }
    }
    private static void yes(String query, String item)
    {
        check(CategoryMatcher.matches(query, item, true), query + " should include " + item);
    }
    private static void no(String query, String item)
    {
        check(!CategoryMatcher.matches(query, item, true), query + " should exclude " + item);
    }
    private static void sameActivity(String shorthand, String original, String sampleItem)
    {
        CategoryMatcher.Query shortQuery = CategoryMatcher.parse("@" + shorthand, true);
        CategoryMatcher.Query originalQuery = CategoryMatcher.parse("@" + original, true);
        check(shortQuery.isExclusive(), "Shortcut not recognized: " + shorthand);
        check(shortQuery.getCategoryName().equals(originalQuery.getCategoryName()),
            "Shortcut " + shorthand + " should resolve to the same category as " + original);
        yes("@" + shorthand, sampleItem);
    }
    public static void runAll()
    {
        checks = 0;
        int[] count = {0};
        Set<String> aliases = new HashSet<>();
        ActivityCategories.register((title, predicate, names) -> {
            count[0]++;
            for (String alias : names)
            {
                check(aliases.add(alias), "Duplicate new alias: " + alias);
                CategoryMatcher.Query q = CategoryMatcher.parse("@" + alias, true);
                check(q.isExclusive(), "Unregistered alias: " + alias);
                check(q.getCategoryName().equals(title), "Incorrect alias owner: " + alias);
            }
        });
        check(count[0] == 71, "Expected 71 activity kits");
        check(CategoryMatcher.catalog().size() >= 219, "Expected at least 219 total categories");
        yes("@herb run", "Ranarr seed");
        yes("@herbrun", "Ranarr seed");
        yes("@herbruns", "Bottomless compost bucket");
        yes("herbrun", "Ectophial");
        no("@herbrun", "Magic seed");
        no("@herbrun", "Grimy ranarr weed");
        check(CategoryMatcher.parse("@herbrun", true).getCategoryName()
            .equals(CategoryMatcher.parse("@herb run", true).getCategoryName()), "herbrun must use existing kit");

        // Karuulm floor heat: all three real boot choices should appear in each kit.
        for (String task : new String[] {
            "@wyrms", "@drakes", "@hydras", "@sulphur lizards"
        })
        {
            yes(task, "Boots of stone");
            yes(task, "Boots of brimstone");
            yes(task, "Granite boots");
            yes(task, "Rada's blessing 4");
            yes(task, "Slayer helmet (i)");
            no(task, "Wyrm bones");
            no(task, "Rune platebody");
        }
        sameActivity("wyrm task", "wyrms", "Dragon hunter lance");
        sameActivity("drake task", "drakes", "Super antifire potion(4)");
        sameActivity("hydra task", "hydras", "Antipoison(4)");
        sameActivity("sulfur lizards", "sulphur lizards", "Cannonball");

        yes("@wyrms", "Rune crossbow");
        yes("@wyrms", "Super restore(4)");
        no("@wyrms", "Antifire potion(4)"); // Wyrms do not breathe dragonfire.
        no("@wyrms", "Cannonball"); // Karuulm Wyrm chamber excludes cannons.
        no("@wyrms", "Dragon sword"); // A loot drop, not preparation equipment.

        yes("@drakes", "Antifire potion(4)");
        yes("@drakes", "Dragonfire shield");
        yes("@drakes", "Super antifire potion(4)");
        no("@drakes", "Drake's claw"); // A drop, not something to bring.

        yes("@hydras", "Superantipoison(4)");
        yes("@hydras", "Cannonball");
        yes("@hydras", "Dragon hunter crossbow");
        no("@hydras", "Hydra bones");
        no("@hydras", "Hydra's eye");
        // Keep the older @hydra and @hydra boss shortcuts for the boss kit.
        check(CategoryMatcher.parse("@hydra", true).getCategoryName()
            .equals("Alchemical Hydra preparation"), "@hydra boss alias changed");
        check(CategoryMatcher.parse("@hydras", true).getCategoryName()
            .equals("Hydras task"), "@hydras should target regular Slayer Hydras");

        yes("@sulphur lizards", "Cannon base");
        yes("@sulphur lizards", "Granite cannonball");
        no("@sulphur lizards", "Ice cooler");
        no("@sulphur lizards", "Lizard");

        // Two curated inclusions and negative controls for all 71 activity kits.
        yes("@zulrah", "anti venom"); yes("@zulrah", "antivenom"); no("@zulrah", "Grimy ranarr weed"); no("@zulrah", "Rune platebody");
        yes("@vorkath", "dragon hunter crossbow"); yes("@vorkath", "dragon hunter lance"); no("@vorkath", "Grimy ranarr weed"); no("@vorkath", "Rune platebody");
        yes("@muspah", "sapphire dragon bolts"); yes("@muspah", "sapphire bolts"); no("@muspah", "Grimy ranarr weed"); no("@muspah", "Rune platebody");
