package com.smartbanksearch;

import org.junit.Test;
import java.util.List;
import static org.junit.Assert.*;

public class CategoryDirectoryModelTest
{
    @Test public void usesAllRegisteredCategoriesAndSearchesBothAliasesAndTitles()
    {
        CategoryDirectoryModel model = new CategoryDirectoryModel();
        assertEquals(CategoryMatcher.catalog().size(), model.size());
        assertTrue(model.size() >= 212);
        assertEquals(model.size(), model.filter("").size());

        assertEquals(1, model.filter("@gotr").size());
        assertEquals("Guardians of the Rift kit", model.filter("@gotr").get(0).title);
        assertEquals(1, model.filter("guardians of the rift").size());
        assertEquals(1, model.filter("cerberus").size());
        assertEquals(1, model.filter("@cerb").size());
        assertEquals(1, model.filter("@chinchompa hunting").size());
        assertEquals(1, model.filter("@cannon tasks").size());
        // The directory uses substring search: "attack" intentionally matches
        // additional headings or aliases such as attack-related gear.
        assertTrue(model.filter("@attack").stream()
            .anyMatch(entry -> entry.title.equals("Attack skill")));

        List<CategoryDirectoryModel.Entry> herbMatches = model.filter("herb");
        assertTrue(herbMatches.size() > 3);
        assertEquals(0, model.filter("this-is-not-a-real-category-12345").size());
    }

    @Test public void favoriteStarIsVisibleWithoutChangingCategorySearchData()
    {
        CategoryDirectoryModel model = new CategoryDirectoryModel();
        CategoryDirectoryModel.Entry gotr = model.filter("@gotr").get(0);

        String normalLabel = gotr.displayLabel(false);
        String favoriteLabel = gotr.displayLabel(true);
        assertTrue("Favorited category must show a star", favoriteLabel.startsWith("\u2605 "));
        assertFalse("Non-favorite category must not show a star", normalLabel.contains("\u2605"));
        assertTrue(favoriteLabel.endsWith(gotr.toString()));
        assertTrue(normalLabel.endsWith(gotr.toString()));

        // Decoration must not change canonical data or category matching.
        assertEquals("Guardians of the Rift kit", gotr.title);
        assertTrue(gotr.contains("@gotr"));
        assertEquals(1, model.filter("@gotr").size());
    }

    @Test public void primaryAliasAlwaysResolvesToDisplayedCategory()
    {
        CategoryDirectoryModel model = new CategoryDirectoryModel();
        for (CategoryDirectoryModel.Entry entry : model.filter(""))
        {
            assertFalse(entry.aliases.isEmpty());
            boolean focused = entry.title.endsWith(" boosts") || entry.title.equals("Prayer restores");
            String search = focused ? entry.primaryAlias : "@" + entry.primaryAlias;
            assertEquals(entry.title,
                CategoryMatcher.parse(search, true).getCategoryName());
            for (String alias : entry.aliases)
            {
                assertTrue("Missing searchable alias: " + alias, entry.contains(alias));
            }
        }
    }
}

package com.smartbanksearch;

/** Standalone assertions that can run with plain javac/java, no RuneLite dependencies. */
public final class CategoryMatcherSelfTest
{
    private static int tests;
    private static void test(boolean condition, String description)
    {
        tests++;
        if (!condition) { throw new AssertionError("FAILED #" + tests + ": " + description); }
    }
    private static void yes(String query, String item)
    {
        test(CategoryMatcher.matches(query, item, true), query + " -> " + item);
    }
    private static void no(String query, String item)
    {
        test(!CategoryMatcher.matches(query, item, true), query + " -/-> " + item);
    }
    public static void main(String[] args)
    {
        test(CategoryMatcher.catalog().size() >= 120, "at least 120 categories");
        yes("herb", "Grimy ranarr weed"); yes("herb", "Torstol"); yes("herb", "Guam leaf"); no("herb", "Ranarr seed");
        yes("seeds", "Yew sapling"); yes("herb seeds", "Ranarr seed"); no("herb seeds", "Magic seed");
        yes("boots", "Primordial boots"); yes("gloves", "Barrows gloves"); yes("bottoms", "Masori chaps");
        yes("dragon fighting equipment", "Anti-dragon shield"); yes("dragon fighting equipment", "Dragon hunter lance"); no("dragon fighting equipment", "Dragon platelegs");
        yes("ore", "Runite ore"); yes("logs", "Yew logs"); yes("bars", "Gold bar"); yes("runes", "Blood rune"); no("runes", "Rune platebody");
        // Regular and combination combat boosts should be found by skill.
        yes("attack", "Attack potion(4)");
        yes("@attack", "Attack potion(1)");
        yes("@attack", "Attack mix(2)");
        yes("@attack", "Super attack(4)");
        yes("@attack", "Divine super attack potion(4)");
        yes("@attack", "Superattack mix(2)");
        yes("@attack", "Combat potion(4)");
        yes("@attack", "Combat mix(2)");
        yes("@attack", "Super combat potion(4)");
        yes("@attack", "Divine super combat potion(4)");
        yes("@attack", "Zamorak brew(4)");
        no("@attack", "Ranging potion(4)");
        no("@attack", "Strength potion(4)");
        yes("@strength", "Combat potion(4)");
        yes("@strength", "Super combat potion(4)");
        yes("@defence", "Super combat potion(4)");
        no("@defence", "Combat potion(4)");
        yes("@combat pots", "Attack potion(4)");
        yes("@combat pots", "Strength potion(4)");
        yes("@combat pots", "Defence potion(4)");
        yes("prayer pots", "Prayer potion(4)"); yes("antipoisons", "Antidote++(4)"); yes("teleport", "Games necklace(8)"); yes("teleport", "Varrock teleport");
        yes("cannon", "Cannonball"); yes("gwd", "Bandos chestplate"); yes("toa", "Osmumten's fang");
        ItemFacts c = new ItemFacts("Masori chaps",7,true,false,0,50,0,0,0,0,0,50);
        test(CategoryMatcher.matches("ranged legs",c,true), "combined ranged legs");
        test(!CategoryMatcher.matches("ranged boots",c,true), "combined excludes unrelated slot");
        ItemFacts p = new ItemFacts("Devout boots",10,true,false,0,0,0,0,0,0,5,2);
        test(CategoryMatcher.matches("@prayer boots",p,true), "exclusive prayer boots");
        test(CategoryMatcher.parse("@rune",true).isExclusive(), "exclusive @rune recognized");
        test(!CategoryMatcher.parse("tag:raid",true).isCategory(), "bank tag syntax untouched");
        test(!CategoryMatcher.parse("ge > 1m",true).isCategory(), "GE search untouched");
        System.out.println("PASS " + tests + " self-tests; " + CategoryMatcher.catalog().size() + " categories available.");
    }
}

